import{_ as e,o as d,c as l,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const f=JSON.parse('{"title":"Page 6","description":"","frontmatter":{},"headers":[],"relativePath":"page-6.md","filePath":"page-6.md"}'),n={name:"page-6.md"};function a(c,t,r,i,s,g){return d(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="page-6" tabindex="-1">Page 6 <a class="header-anchor" href="#page-6" aria-label="Permalink to &quot;Page 6&quot;">​</a></h1><h3 id="常用算法函数" tabindex="-1">常用算法函数 <a class="header-anchor" href="#常用算法函数" aria-label="Permalink to &quot;常用算法函数&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>reverse(begin, end)</code></td><td style="text-align:left;">逆序 <code>[begin, end)</code> 区间内的元素，<code>O(n)</code></td></tr><tr><td style="text-align:left;"><code>sort(begin, end, cmp)</code></td><td style="text-align:left;">将 <code>[begin, end)</code> 按 <code>cmp</code> 排序，默认升序，<code>O(n log n)</code></td></tr><tr><td style="text-align:left;"><code>stable_sort(begin, end, cmp)</code></td><td style="text-align:left;">稳定排序，相等元素保持原相对顺序</td></tr><tr><td style="text-align:left;"><code>unique(begin, end)</code></td><td style="text-align:left;">去重（需先排序），返回新序列的末尾迭代器</td></tr><tr><td style="text-align:left;"><code>random_shuffle(begin, end)</code></td><td style="text-align:left;">随机打乱 <code>[begin, end)</code> 区间（C++14 起已弃用）</td></tr><tr><td style="text-align:left;"><code>shuffle(begin, end, gen)</code></td><td style="text-align:left;">C++11 随机打乱，使用随机数生成器 <code>gen</code></td></tr><tr><td style="text-align:left;"><code>lower_bound(begin, end, x)</code></td><td style="text-align:left;">二分查找第一个 <strong>&gt;= x</strong> 的元素位置</td></tr><tr><td style="text-align:left;"><code>upper_bound(begin, end, x)</code></td><td style="text-align:left;">二分查找第一个 <strong>&gt; x</strong> 的元素位置</td></tr><tr><td style="text-align:left;"><code>binary_search(begin, end, x)</code></td><td style="text-align:left;">二分判断 <code>x</code> 是否存在，返回 <code>bool</code></td></tr><tr><td style="text-align:left;"><code>next_permutation(begin, end)</code></td><td style="text-align:left;">生成下一组字典序排列（原地修改），返回是否还有下一排列</td></tr><tr><td style="text-align:left;"><code>prev_permutation(begin, end)</code></td><td style="text-align:left;">生成上一组字典序排列（原地修改），返回是否还有上一排列</td></tr><tr><td style="text-align:left;"><code>max(a, b)</code> / <code>min(a, b)</code></td><td style="text-align:left;">返回两个数中的较大/较小值</td></tr><tr><td style="text-align:left;"><code>max_element(begin, end)</code></td><td style="text-align:left;">返回区间内最大元素的迭代器</td></tr><tr><td style="text-align:left;"><code>min_element(begin, end)</code></td><td style="text-align:left;">返回区间内最小元素的迭代器</td></tr><tr><td style="text-align:left;"><code>swap(a, b)</code></td><td style="text-align:left;">交换两个变量的值</td></tr><tr><td style="text-align:left;"><code>fill(begin, end, val)</code></td><td style="text-align:left;">将 <code>[begin, end)</code> 区间所有元素赋值为 <code>val</code></td></tr><tr><td style="text-align:left;"><code>copy(src_begin, src_end, dst_begin)</code></td><td style="text-align:left;">将源区间复制到目标位置</td></tr></tbody></table><p><strong>C 风格内存操作</strong>（<code>&lt;cstring&gt;</code>）</p><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>memset(ptr, value, size)</code></td><td style="text-align:left;">将 <code>ptr</code> 起始的 <code>size</code> 个字节设为 <code>value</code>（按字节赋值）</td></tr><tr><td style="text-align:left;"><code>memcpy(dest, src, size)</code></td><td style="text-align:left;">将 <code>src</code> 起始的 <code>size</code> 个字节复制到 <code>dest</code>（不处理重叠）</td></tr><tr><td style="text-align:left;"><code>memmove(dest, src, size)</code></td><td style="text-align:left;">同 <code>memcpy</code>，但可安全处理内存重叠</td></tr><tr><td style="text-align:left;"><code>memcmp(ptr1, ptr2, size)</code></td><td style="text-align:left;">比较两段内存前 <code>size</code> 个字节，返回差值</td></tr><tr><td style="text-align:left;"><code>memchr(ptr, value, size)</code></td><td style="text-align:left;">在 <code>ptr</code> 起始的 <code>size</code> 字节中查找 <code>value</code>，返回首次出现位置的指针</td></tr></tbody></table>',5)])])}const y=e(n,[["render",a]]);export{f as __pageData,y as default};
